#include "stdafx.h"#include "MessageList.h"#include <FormatScn.h>#include <../Utils/Utils/ListValue.h>CMessageList::CMessageList(void): m_list(NULL), m_nCount(0){  Open();}CMessageList::~CMessageList(void){  BuffFree(m_list);}bool CMessageList::Realloc(){  if ( (m_nCount % STEP_REALLOC) == 0 )  {    SMessage* t = (SMessage*)BuffAlloc((m_nCount+STEP_REALLOC)*sizeof(SMessage),true);    if ( t == NULL ) return false;    else    {      if ( m_list != NULL )      {        memcpy(t,m_list,m_nCount*sizeof(SMessage));        BuffFree(m_list);      }      m_list = t;    }  }  return true;}void CMessageList::Open(){  char szFile[_MAX_PATH];  sprintf_s( szFile, "%sMessages.scn", GetAcyPath() );  char* szBuffer = ::FileToBuff( szFile );  if ( szBuffer != NULL )  {    Parser( szBuffer );    ::BuffFree( szBuffer );  }}int SortMessage(const void * d1, const void * d2 ) {  SMessage* p1 = (SMessage*)d1;  SMessage* p2 = (SMessage*)d2;  int nReturn = strcmp( p1->szName, p2->szName );  if ( nReturn == 0 )  {    if ( p1->eData < p2->eData ) return -1;    if ( p1->eData > p2->eData ) return  1;  }  return nReturn;}void CMessageList::Parser( char* ptr ){  SMessage obj;  char* pszValue;  STegScn* scn = NULL;  int nCount = 0;  while ( 1 )  {    int nReturn = ParserSCN( ptr, scn, nCount );    if ( nReturn <= 0 ) break;    //    if ( !*scn[0].value ) continue;    pszValue = NULL;    memset( &obj, 0, sizeof(obj) );    StrCPY( obj.szName, scn[0].value, sizeof(obj.szName) );    //    int m = 1;    while ( scn[m].name && scn[m].value )    {      if ( lstrcmpi( scn[m].name, "value" ) == 0 )        pszValue = scn[m].value;      else        if ( lstrcmpi( scn[m].name, "filtr" ) == 0 )          StrCPY( obj.szFiltr, scn[m].value, sizeof(obj.szFiltr) );        else          if ( lstrcmpi( scn[m].name, "string" ) == 0 )            obj.nAsString = atoi(scn[m].value);          else            if ( lstrcmpi( scn[m].name, "name" ) == 0 )              obj.nOnlyName = atoi(scn[m].value);            else              if ( _strnicmp( scn[m].name, "txt", 3 ) == 0 )              {                int k = atoi( scn[m].name+3 );                if ( 0 <= k && k < 16 )                  StrCPY( obj.szTxt[k], scn[m].value, sizeof(obj.szTxt[k]) );              }              m++;    }    //    if ( pszValue == NULL ) pszValue = scn[0].value;    //    STagType* find = FindTagType( scn[0].name );    if ( find == NULL )       continue;    obj.def   = NameToValue(find->eType, pszValue);    obj.eData = find->eType;    //    if ( obj.def == NULL ) continue;    //    if ( !Realloc() )      break;    m_list[m_nCount++] = obj;  }  ::ParserFree( scn );  qsort( m_list, m_nCount, sizeof (SMessage), SortMessage );}